root.addEventListener('click',ev=>{const b=ev.target.closest('button,a');if(!b)return;if(previewSession&&b.dataset.action&&!canAccountAction(b.dataset.action)){toast('当前账号无此操作权限');return;}if(b.dataset.intakeOpen){role='dispatch';selected=b.dataset.intakeOpen;navigate('orders',false);backendPanel='details';render();}else if(b.dataset.intakeRequest){selected=b.dataset.intakeRequest;openAction('requestExternalDispatch');}else if(b.dataset.driverGroup){driverGroup=b.dataset.driverGroup;driverPage=1;render();}else if(b.dataset.driverPage){driverPage=+b.dataset.driverPage;render();}else if(b.dataset.driverOpen){selected=b.dataset.driverOpen;driverTab='tasks';render();}else if(b.dataset.center){changeRole(b.dataset.center==='ops'?'ops':'dispatch');}else if(b.dataset.sectionTab){sectionTab=b.dataset.sectionTab;render();}else if(b.dataset.resource){selectedResource=b.dataset.resource;sectionTab='details';render();if(b.dataset.editWarehouse)openAction('warehouseEdit');}else if(b.dataset.backendTab){backendPanel=b.dataset.backendTab;render();}else if(b.dataset.bookingTab){bookingTab=b.dataset.bookingTab;render();}else if(b.dataset.nav){ev.preventDefault();navigate(b.dataset.nav);}else if(b.dataset.role)changeRole(b.dataset.role);else if(b.dataset.partner){selectedPartner=b.dataset.partner;sectionTab='details';render();}else if(b.dataset.payable){selectedPayable=b.dataset.payable;sectionTab='details';render();}else if(b.dataset.dispatchTab){dispatchTab=b.dataset.dispatchTab;if(dispatchTab==='map'&&current()?.vehicle)mapVehicle=current().vehicle;query='';filter='all';page=1;render();document.querySelector(`[data-dispatch-tab=${dispatchTab}]`)?.focus();}else if(b.dataset.incidentInspect){selected=b.dataset.incidentInspect;query='';filter='all';render();const card=document.querySelector('.fleet-inspector .incident-card');if(card){card.querySelector('details').open=true;card.scrollIntoView({block:'nearest',behavior:'instant'});}}else if(b.dataset.fleet){selectFleet(b.dataset.fleet);}else if(b.dataset.mapOrder){selected=b.dataset.mapOrder;if(current()?.vehicle)mapVehicle=current().vehicle;query='';filter='all';render();}else if(b.dataset.alertOrder){dispatchTab='orders';selected=b.dataset.alertOrder;query=selected;filter='all';page=1;tab='overview';render();document.querySelector('#order-workspace')?.scrollIntoView({block:'start',behavior:'instant'});}else if(b.dataset.stage){dispatchTab='orders';filter=b.dataset.stage;query='';page=1;render();document.querySelector('#order-workspace')?.scrollIntoView({block:'start',behavior:'instant'});}else if(b.dataset.order){selected=b.dataset.order;tab='overview';backendPanel='details';render();}else if(b.dataset.filter){filter=b.dataset.filter;page=1;render();}else if(b.dataset.tab){tab=b.dataset.tab;render();}else if(b.dataset.driverTab){driverTab=b.dataset.driverTab;render();}else if(b.dataset.mode){if(b.dataset.mode==='offline'){role='driver';driverTab='tasks';}view=role==='ops'?'operations':role==='partnerDriver'?'driver':role;mode=b.dataset.mode;render();}else if(b.dataset.action){const a=b.dataset.action;if(a==='driver-clear-search'){driverSearch='';driverPage=1;render();document.querySelector('#driver-order-search')?.focus();}else if(a==='fleet-assign'){const v=fleetRows(db).find(v=>v.id===mapVehicle);openAction(v?.partnerId?'partnerOffer':'offer');const input=dialog.querySelector(`[name=vehicle][value="${mapVehicle}"]`);if(input&&!input.disabled)input.checked=true;const sel=dialog.querySelector('[name=partnerId]');if(sel&&v?.partnerId)sel.value=v.partnerId;}else if(a==='dispatch-details'){dispatchTab='orders';query=selected;render();const d=document.querySelector('.order-expand');if(d)d.open=true;}else if(a.startsWith('fleet-')){fleetZoom=a==='fleet-zoom-in'?Math.min(1.6,fleetZoom+.2):a==='fleet-zoom-out'?Math.max(1,fleetZoom-.2):1;render();}else if(a==='busy-scenario'){db=addDispatchScenario(db);save();render();toast('已补充合成演示订单，保留已有流程进度。');}else if(a==='all-alerts'){navigate('exceptions');}else if(a.startsWith('map-')){mapZoom=a==='map-in'?Math.min(2,mapZoom+.25):a==='map-out'?Math.max(.8,mapZoom-.25):1;const canvas=document.querySelector('.driver-map');if(canvas)canvas.outerHTML=driverMap(current());if(a==='map-center')toast('已回到司机演示位置，尚未接入真实定位。');}else if(a==='qa')navigate('prototype');else if(a==='normal'){mode='normal';render();}else if(a==='clear-search'){query='';filter='all';page=1;render();document.querySelector('#search')?.focus();}else if(a==='prev'||a==='next'){page+=a==='next'?1:-1;render();}else if(a==='sync')syncQueue();else openAction(a);}});
function searchInput(ev){if(ev.target.id!=='search'||ev.isComposing)return;query=ev.target.value;page=1;const position=ev.target.selectionStart;render();const input=document.querySelector('#search');input?.focus();input?.setSelectionRange(position,position);}
root.addEventListener('input',searchInput);root.addEventListener('compositionend',searchInput);root.addEventListener('change',ev=>{if(ev.target.id==='mobile-nav')navigate(ev.target.value);if(ev.target.id==='driver-actor'){driverActor=ev.target.value;selected=null;driverSearch='';driverPage=1;render();}if(ev.target.id==='fleet-selector')selectFleet(ev.target.value);if(ev.target.id==='map-order-selector'){selected=ev.target.value;const o=current();if(o?.vehicle)mapVehicle=o.vehicle;render();}});
dialog.addEventListener('click',ev=>{if(ev.target.closest('[data-close]'))closeDialog();});dialog.addEventListener('input',()=>{dirty=true;const err=dialog.querySelector('#form-error');if(err)delete err.dataset.discard;});dialog.addEventListener('cancel',ev=>{ev.preventDefault();closeDialog();});dialog.addEventListener('submit',ev=>{ev.preventDefault();submit(ev.target);});
window.addEventListener('beforeunload',ev=>{if(dirty||hasAreaDraft()||hasAccessDraft()){ev.preventDefault();ev.returnValue='';}});
setInterval(()=>{if(busy||dialog.open)return;const next=expire(db);if(next.orders.some((o,i)=>o.version!==db.orders[i].version)){db=next;save();render();toast('提案已过期，订单已回到待派队列。');}},5000);
save();render();
if(entryKind==='web'){try{startAccountPreview(entryParams.get('account'));}catch(error){toast(error.message);}}else if(['driver','customer'].includes(entryKind)){changeRole(entryKind);showHomeAnnouncement(entryKind);}

root.addEventListener('keydown',ev=>{if(!ev.target.matches('[data-dispatch-tab]'))return;const keys=['map','orders','alerts','overview'],i=keys.indexOf(dispatchTab);if(['ArrowLeft','ArrowRight','Home','End'].includes(ev.key)){ev.preventDefault();dispatchTab=ev.key==='Home'?keys[0]:ev.key==='End'?keys[3]:keys[(i+(ev.key==='ArrowRight'?1:3))%4];query='';filter='all';if(dispatchTab==='map'&&current()?.vehicle)mapVehicle=current().vehicle;render();document.querySelector(`[data-dispatch-tab=${dispatchTab}]`).focus();}});

dialog.addEventListener('change',ev=>{if(ev.target.id==='f-goodsId'){const g=db.goods.find(g=>g.id===ev.target.value);if(g)for(const [key,value]of Object.entries({cargo:g.name,weight:g.weight,length:g.length,width:g.width,height:g.height})){const input=dialog.querySelector(`[name=${key}]`);if(input)input.value=value;}}});

dialog.addEventListener('change',ev=>{if(ev.target.name==='quoteMode'){dialog.querySelector('#distance-fields').open=ev.target.value==='distance';}});

function driverSearchInput(ev){if(ev.target.id!=='driver-order-search'||ev.isComposing)return;driverSearch=ev.target.value;driverPage=1;const pos=ev.target.selectionStart;render();const el=document.querySelector('#driver-order-search');el?.focus();el?.setSelectionRange(pos,pos);}root.addEventListener('input',driverSearchInput);root.addEventListener('compositionend',driverSearchInput);
setInterval(()=>{if(isDriver()&&driverTab==='orders'&&!dialog.open&&document.activeElement?.id!=='driver-order-search')render();},30000);

dialog.addEventListener('click',ev=>{if(!ev.target.closest('[data-parse-external]'))return;const feedback=dialog.querySelector('#parse-feedback');try{const result=parseExternalText(dialog.querySelector('#external-paste').value);for(const [name,value]of Object.entries(result.fields)){const input=dialog.querySelector(`[name="${name}"]`)||(name==='sourceSystem'?dialog.querySelector('[name=sourcePlatform]'):null);if(input)input.value=value;}feedback.textContent=`识别 ${Object.keys(result.fields).length} 项。`+(result.warnings.length?result.warnings.join('；'):'请逐项校对后再确认导入。');dirty=true;dialog.querySelector('[name=reviewed]').checked=false;}catch(error){feedback.textContent=error.message;}});

setInterval(()=>{if(role==='finance'&&!dialog.open&&!document.hidden){const next=checkSettlements(db);if(next!==db){db=next;save();render();}}},60000);
